import { Component, Prop, h } from '@stencil/core';

@Component({
  tag: 'std-box',
  styleUrl: 'std-box.css',
  shadow: true
})
export class StdBoxComponent {
  @Prop() classes: string;
  @Prop() tooltips: boolean;
  @Prop() tooltipPosition: string;
  @Prop() label: string; // title
  @Prop() link: boolean;
  @Prop() html: string;
  @Prop() labelLink: string;
  @Prop() iconLink: string;
  @Prop() classesLink: string;

  render() {
    const boxClasses = ['rounded-lg flex flex-col gap-5 p-6 border border-alternative-medium lg:flex-1', this.classes].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class={boxClasses}>
        <div class="flex items-center justify-between flex-wrap gap-2">
          <h3 class="relative after:content-[''] after:absolute after:-bottom-2 after:left-0 after:w-6 after:h-[2px] after:bg-primary text-dark text-lg font-bold flex items-center gap-2">
            {this.label}
            {this.tooltips && (
              <std-tooltip position={this.tooltipPosition} classes="std-box" classes-header="group relative flex">
                {this.html}
                <div slot="html">
                  <div class="flex">
                    <i class="icon-information-in-a-circle-2px !text-primary text-xl leading-none" />
                  </div>
                </div>
              </std-tooltip>
            )}
          </h3>
          {this.link && <std-link label={this.labelLink} icon={this.iconLink} iconPosition="left" classes={this.classesLink} />}
          <slot name="actions" />
        </div>
        <div>
          <slot />
        </div>
      </div>
    );
  }
}
